let theShader;
let WebGL;
let Canvas;
let img0, img1, img2;
let deltaX = 0, deltaY = 0;

function preload(){
  theShader = createShader(vert, frag);
	// get images from https://github.com/ZRNOF/Photos-for-image-processing
	img0 = loadImage(get_image_url("Rain_Window_01.jpg"));
	img1 = loadImage(get_image_url("Tunnel_01.jpg"));
	img2 = loadImage(get_image_url("The_Dome_of_Light_02.jpg"));
}

function setup() {
  createCanvas(1024, 576);
  pixelDensity(1);
  WebGL = createGraphics(width, height, WEBGL);
  Canvas = createGraphics(width, height);
  noStroke();
	background(51);
}

function draw() {
  deltaX += map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0.5, -0.5);
  deltaY += map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0.5, -0.5);

	WebGL.shader(theShader);

  theShader.setUniform('iResolution', [width, height]);
	theShader.setUniform('iPixelDensity', pixelDensity());
	theShader.setUniform('iCanvas', Canvas);
	theShader.setUniform('iImage0', img0);
	theShader.setUniform('iImage1', img1);
	theShader.setUniform('iImage2', img2);
  theShader.setUniform('iMouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  theShader.setUniform('iTime', frameCount);
  theShader.setUniform('iDelta', [deltaX, deltaY]);

  WebGL.rect(0, 0, width, height);

  image(WebGL, 0, 0);
	Border("#FFFFFF", 10);

	ClickStop();
}

// see https://github.com/ZRNOF/Photos-for-image-processing
function get_image_url(filename) {
  let root = "https://raw.githubusercontent.com/ZRNOF/Photos-for-image-processing/main/Package/";
  return root + filename;
}

function Border(color, weight) {
  push();
  noFill();
  stroke(color);
  strokeWeight(weight*2);
  rectMode(CENTER);
  rect(width/2, height/2, width, height);
  pop();
}

