	// Image extend mode - hold
	vec4 hold(vec2 uv, sampler2D img) {
		return texture2D(img, uv);
	}

	// Image extend mode - mirror
	vec4 mirror(vec2 uv, sampler2D img) {
		vec2 iuv = floor(uv);
		uv *= 1.-2.*mod(iuv, 2.);
		return texture2D(img, fract(uv));
	}

	// Image extend mode - one
	vec4 one(vec2 uv, sampler2D img) {
		if (0. <= uv.x && uv.x <= 1. && 0. <= uv.y && uv.y <= 1.) {
			return texture2D(img, uv);
		}
		else { return vec4(1.); }
	}

	// Image extend mode - repeat
	vec4 repeat(vec2 uv, sampler2D img) {
		return texture2D(img, fract(uv));
	}

	// Image extend mode - zero
	vec4 zero(vec2 uv, sampler2D img) {
		if (0. <= uv.x && uv.x <= 1. && 0. <= uv.y && uv.y <= 1.) {
			return texture2D(img, uv);
		}
		else { return vec4(0.); }
	}

	// Coordinate extend mode - mirror
	vec2 mirror(vec2 uv, float num) {
		uv *= num;
		vec2 iuv = floor(uv);
		uv *= 1.-2.*mod(iuv, 2.);
		return fract(uv);
	}

	// Coordinate extend mode - repeat
	vec2 repeat(vec2 uv, float num) {
		return fract(uv*num);
	}
`

// === Tab: frag ===
// noprotect

const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	uniform vec2 iResolution;
	uniform float iPixelDensity;
	uniform sampler2D iCanvas;
	uniform sampler2D iImage0;
	uniform sampler2D iImage1;
	uniform sampler2D iImage2;
	uniform vec2 iMouse;
	uniform float iTime;
	uniform vec2 iDelta;

	${ snoise3D }
	${ snoise3DImage }
	${ displace }
	${ extendMode }

	vec4 noiseImage(vec2 uv, float scal, float gain, float ofst, vec3 move) {
		vec4 dimg = 1.0*snoise3DImage((uv-vec2(421., 132))*1., scal, gain, ofst, move);
		dimg +=    0.25*snoise3DImage((uv-vec2(834., 724))*4., scal, gain, ofst, move);
		dimg +=  0.0625*snoise3DImage((uv-vec2(387., 99))*16., scal, gain, ofst, move);
		return dimg/1.3125;
	}

	varying vec2 vTexCoord;
	void main() {
		vec2 uv = vTexCoord;
		vec2 mouse = iMouse.xy/iResolution.xy;
		uv.y = 1.-uv.y;

		vec3 trans = vec3(iDelta.x, iDelta.y, iTime*0.002);
		vec4 dimg = noiseImage(uv, 1., 1., .5, trans);

		vec2 duv = displace(uv, dimg.rb, .5, 3.);
		duv = mirror(duv, 1.);

		vec4 img0 = texture2D(iImage0, duv);
		vec4 img1 = texture2D(iImage1, duv);
		vec4 img2 = texture2D(iImage2, duv);

		// fade slideshow
		vec4 col;
		float time = iTime*.005;
		float it = floor(time);
		float grad = .5+.5*sin((fract(time)-.5)*3.14159);
		if (mod(it, 3.) == 0.) { col = mix(img0, img1, grad); }
		if (mod(it, 3.) == 1.) { col = mix(img1, img2, grad); }
		if (mod(it, 3.) == 2.) { col = mix(img2, img0, grad); }

		gl_FragColor = col;
	}
`

// === Tab: vert ===
// Basic structure ref: https://itp-xstory.github.io/p5js-shaders/#/./docs/how-to-write-a-shader

const vert = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	varying vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
		gl_Position = positionVec4;
	}
`

